typedef struct _FSIBusInsert {
    bool has_type;
    uint32_t type;
    bool has_bypass;
    bool bypass;
    // =============================================================================
    // Insert identities are local to their bus and are not reused.
    // =============================================================================
    bool has_stable_id;
    uint32_t stable_id;
    pb_size_t params_count;
    float params[8];
} FSIBusInsert;

typedef struct _FSIBusSend {
    // =============================================================================
    // Zero-based aux bus number. Only an output bus carries sends.
    // =============================================================================
    bool has_dest;
    uint32_t dest;
    bool has_level;
    float level;
    bool has_pre_fader;
    bool pre_fader;
} FSIBusSend;

typedef struct _FSIBus {
    bool has_name;
    char name[64];
    bool has_volume;
    float volume;
    bool has_pan;
    float pan;
    bool has_output;
    uint32_t output;
    // =============================================================================
    // Inserts process the summed bus, in this order.
    // =============================================================================
    pb_size_t inserts_count;
    FSIBusInsert inserts[8];
    // =============================================================================
    // Only the sends that are switched on are stored. An absent send is off.
    // =============================================================================
    pb_size_t sends_count;
    FSIBusSend sends[8];
} FSIBus;

typedef struct _FSICollection {
    char name[64];
    uint32_t zone_count;
    uint32_t modulator_count;
    uint32_t first_zone_index;
    bool has_flags;
    uint32_t flags;
    // =============================================================================
    // Capture bounds are fractions of each zone's playing region.
    // Absent bounds select the loop, or 15 to 85 percent when no loop exists.
    // =============================================================================
    bool has_smf_capture_manual;
    bool smf_capture_manual;
    bool has_smf_capture_start;
    float smf_capture_start;
    bool has_smf_capture_end;
    float smf_capture_end;
    // =============================================================================
    // Use stable IDs for links. The loader assigns missing IDs in collection
    // order.
    // =============================================================================
    bool has_stable_id;
    uint32_t stable_id;
    bool has_output_bus;
    uint32_t output_bus;
    // =============================================================================
    // The stable ID of the collection whose release samples this one holds.
    // =============================================================================
    bool has_release_of;
    uint32_t release_of;
} FSICollection;

typedef struct _FSIZone {
    char name[64];
    float attack;
    float decay;
    float sustain;
    float release;
    uint32_t startframe;
    uint32_t endframe;
    uint32_t loopstart;
    uint32_t loopend;
    uint32_t xfadeframes;
    uint32_t xfadetype;
    float volume;
    float pitch;
    bool has_loop_enabled;
    bool loop_enabled;
    bool has_oneshot;
    bool oneshot;
    bool has_is_release_sample;
    bool is_release_sample;
    bool has_ignore_vel_mapping;
    bool ignore_vel_mapping;
    bool has_low_note;
    uint32_t low_note;
    bool has_high_note;
    uint32_t high_note;
    bool has_root_note;
    uint32_t root_note;
    bool has_low_velocity;
    uint32_t low_velocity;
    bool has_high_velocity;
    uint32_t high_velocity;
    bool has_pitchshift_type;
    uint32_t pitchshift_type;
    bool has_flip_lr;
    bool flip_lr;
    bool has_zoom_start;
    uint32_t zoom_start;
    bool has_zoom_end;
    uint32_t zoom_end;
    bool has_zoom_v;
    float zoom_v;
    bool has_inframe;
    uint32_t inframe;
    bool has_outframe;
    uint32_t outframe;
    // =============================================================================
    // The two bounds of a legato move, absolute within the zone. An absent or
    // zero frame selects the legato time fallback for that end.
    // =============================================================================
    bool has_arrivalframe;
    uint32_t arrivalframe;
    bool has_departureframe;
    uint32_t departureframe;
    // =============================================================================
    // The one-based index of the source sample this zone plays, and the part of
    // that sample's result the zone plays. Absent or zero means no source.
    // =============================================================================
    bool has_source_sample;
    uint32_t source_sample;
    bool has_source_first;
    uint32_t source_first;
    bool has_source_frames;
    uint32_t source_frames;
} FSIZone;

